import {
  adoptStyles,
  type DefineOptions,
  defineElement,
  ElementBase,
  ensureId,
  rootOf,
} from "../internal/base.js";
import css from "./field.css.js";

type Part = "label" | "hint" | "error";
type Refs = HTMLElement & {
  ariaLabelledByElements?: Element[] | null;
  ariaDescribedByElements?: Element[] | null;
};

/**
 * `<ui-field label="Name" hint="..." error="...">`: a label, a control and the text under it. The
 * control is the first child that is not generated by the field (a native control or any `ui-*`
 * form element). The field gives it an id, points a native `<label for>` at it, and wires
 * `aria-describedby` to the hint and the error and `aria-invalid` (plus `invalid`) to the error.
 * The error is a `role="alert"` paragraph. For a shadow-DOM control such as `<ui-input>` the same
 * references are handed to its inner control, so the real AX tree gets name, description and
 * invalid state.
 *
 * Attributes: `label`, `hint`, `error` (empty or absent: no error), `optional` (appends
 * "(optional)"), `optional-text` (the localized marker, default `optional`).
 */
export class UiField extends ElementBase {
  static observedAttributes = ["label", "hint", "error", "optional", "optional-text"];
  #observer: MutationObserver | undefined;
  #invalid: boolean | undefined;

  connectedCallback(): void {
    this.dataset.ui = "field";
    adoptStyles(rootOf(this), css);
    this.#render();
    this.#observer ??= new MutationObserver((records) => {
      const foreign = (node: Node) =>
        !(node instanceof Element && node.hasAttribute("data-ui-part"));
      if (records.some((r) => [...r.addedNodes, ...r.removedNodes].some(foreign))) this.#render();
    });
    this.#observer.observe(this, { childList: true });
  }

  disconnectedCallback(): void {
    this.#observer?.disconnect();
  }

  attributeChangedCallback(): void {
    if (this.isConnected) this.#render();
  }

  get control(): HTMLElement | null {
    return (
      [...this.children].find(
        (child): child is HTMLElement =>
          child instanceof HTMLElement && !child.hasAttribute("data-ui-part"),
      ) ?? null
    );
  }

  #part(name: Part, tag: string): HTMLElement {
    let part = this.querySelector<HTMLElement>(`:scope > [data-ui-part="${name}"]`);
    if (!part) {
      part = document.createElement(tag);
      part.setAttribute("data-ui-part", name);
    }
    return part;
  }

  #render(): void {
    const control = this.control;
    const controlId = control ? ensureId(control, "field") : "";
    const label = this.#part("label", "label") as HTMLLabelElement;
    const hint = this.#part("hint", "p");
    const error = this.#part("error", "p");
    error.setAttribute("role", "alert");

    const text = this.getAttribute("label") ?? "";
    label.textContent = text;
    if (this.hasAttribute("optional")) {
      const marker = document.createElement("span");
      marker.setAttribute("data-ui-part", "optional");
      marker.textContent = ` (${this.getAttribute("optional-text") ?? "optional"})`;
      label.append(marker);
    }
    label.htmlFor = controlId;
    label.hidden = !text;
    hint.textContent = this.getAttribute("hint") ?? "";
    error.textContent = this.getAttribute("error") ?? "";
    hint.id = controlId ? `${controlId}-hint` : "";
    error.id = controlId ? `${controlId}-error` : "";

    if (label.parentNode !== this || label.nextElementSibling !== control)
      (control ?? this).before(label);
    let anchor: Element | null = control;
    for (const part of [hint, error]) {
      if (part.previousElementSibling !== anchor || part.parentNode !== this)
        (anchor ?? this).after(part);
      anchor = part;
    }
    hint.hidden = !hint.textContent;
    error.hidden = !error.textContent;
    if (control) this.#wire(control, label, hint, error);
  }

  #wire(control: HTMLElement, label: HTMLElement, hint: HTMLElement, error: HTMLElement): void {
    const described = [hint, error].filter((part) => !part.hidden);
    if (described.length)
      control.setAttribute("aria-describedby", described.map((p) => p.id).join(" "));
    else control.removeAttribute("aria-describedby");

    const invalid = !error.hidden;
    if (invalid) {
      control.setAttribute("aria-invalid", "true");
      control.setAttribute("invalid", "");
    } else if (this.#invalid) {
      control.removeAttribute("aria-invalid");
      control.removeAttribute("invalid");
    }
    this.#invalid = invalid;

    const inner = control.shadowRoot?.querySelector<Refs>("input, textarea, select");
    if (inner && "ariaDescribedByElements" in inner) {
      inner.ariaDescribedByElements = described.length ? described : null;
      if (!control.hasAttribute("aria-label") && !control.hasAttribute("label") && !label.hidden)
        inner.ariaLabelledByElements = [label];
    }
  }
}

/** Registers `<ui-field>` (or `<prefix-field>`) and returns the tag. */
export const defineField = (options?: DefineOptions) => defineElement("field", UiField, options);
